{"cmd":"node - <<'NODE'
const fs = require('fs');
const path = require('path');

const root = '/Users/lyston/Documents/Codex/2026-05-26/019e1f23-57e7-7110-ba2c-c18698f4f8ec-documents/session-export-019e1f23-57e7-7110-ba2c-c18698f4f8ec';
const sessionPath = path.join(root, 'raw/session-019e1f23-57e7-7110-ba2c-c18698f4f8ec.jsonl');
const historyPath = path.join(root, 'raw/global-history-snapshot.jsonl');
const outDir = path.join(root, 'readable');
const sessionId = '019e1f23-57e7-7110-ba2c-c18698f4f8ec';

function readJsonl(file) {
  return fs.readFileSync(file, 'utf8')
    .split(/\r?\n/)
    .filter(Boolean)
    .map((line, idx) => {
      try { return { idx: idx + 1, obj: JSON.parse(line), raw: line }; }
      catch (err) { return { idx: idx + 1, error: String(err), raw: line }; }
    });
}

function textFromContent(content) {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content.map(part => {
    if (!part) return '';
    if (typeof part === 'string') return part;
    return part.text || part.input_text || part.output_text || part.content || '';
  }).filter(Boolean).join('\n');
}

function codeFence(text) {
  const fence = text.includes('```') ? '````' : '```';
  return `${fence}\n${text}\n${fence}`;
}

function truncate(text, limit = 1800) {
  if (!text) return '';
  return text.length > limit ? text.slice(0, limit) + `\n... [truncated ${text.length - limit} chars]` : text;
}

const rows = readJsonl(sessionPath);
const metaRow = rows.find(r => r.obj?.type === 'session_meta')?.obj?.payload || {};

let transcript = [];
transcript.push(`# Session Transcript: ${sessionId}`);
transcript.push('');
transcript.push(`- Exported at: ${new Date().toISOString()}`);
transcript.push(`- Source: ${sessionPath}`);
transcript.push(`- Session timestamp: ${metaRow.timestamp || 'unknown'}`);
transcript.push(`- Original cwd: ${metaRow.cwd || 'unknown'}`);
transcript.push(`- Originator: ${metaRow.originator || 'unknown'}`);
transcript.push(`- CLI version: ${metaRow.cli_version || 'unknown'}`);
transcript.push(`- Model provider: ${metaRow.model_provider || 'unknown'}`);
transcript.push('');
transcript.push('> This readable transcript extracts visible user and assistant message text from the raw JSONL. Tool calls, event payloads, encrypted reasoning, and full metadata remain in `raw/session-019e1f23-57e7-7110-ba2c-c18698f4f8ec.jsonl`.');
transcript.push('');

let messageCount = 0;
for (const r of rows) {
  const obj = r.obj;
  if (obj?.type !== 'response_item') continue;
  const payload = obj.payload;
  if (payload?.type !== 'message') continue;
  const role = payload.role || 'unknown';
  if (!['user', 'assistant'].includes(role)) continue;
  const text = textFromContent(payload.content).trim();
  if (!text) continue;
  messageCount++;
  transcript.push(`## ${messageCount}. ${role.toUpperCase()} — ${obj.timestamp || 'unknown'} — line ${r.idx}`);
  transcript.push('');
  transcript.push(text);
  transcript.push('');
}

let timeline = [];
timeline.push(`# Session Timeline: ${sessionId}`);
timeline.push('');
timeline.push(`- Exported at: ${new Date().toISOString()}`);
timeline.push(`- Source lines: ${rows.length}`);
timeline.push('');
timeline.push('This file is a compact index of session events. It preserves timestamps and raw JSONL line numbers so the complete payload can be found in the raw export. Long tool outputs are summarized here.');
timeline.push('');

const counters = {};
for (const r of rows) {
  const obj = r.obj;
  if (!obj) {
    timeline.push(`## Line ${r.idx} — parse_error`);
    timeline.push('');
    timeline.push(r.error || 'Unknown parse error');
    timeline.push('');
    continue;
  }
  counters[obj.type] = (counters[obj.type] || 0) + 1;
  const ts = obj.timestamp || 'unknown';
  const type = obj.type;
  let title = type;
  let body = '';

  if (type === 'session_meta') {
    title = 'session_meta';
    body = [
      `id: ${obj.payload?.id || ''}`,
      `cwd: ${obj.payload?.cwd || ''}`,
      `originator: ${obj.payload?.originator || ''}`,
      `cli_version: ${obj.payload?.cli_version || ''}`,
      `source: ${obj.payload?.source || ''}`,
      `model_provider: ${obj.payload?.model_provider || ''}`,
    ].join('\n');
  } else if (type === 'turn_context') {
    title = 'turn_context';
    body = [
      `turn_id: ${obj.payload?.turn_id || ''}`,
      `cwd: ${obj.payload?.cwd || ''}`,
      `current_date: ${obj.payload?.current_date || ''}`,
      `timezone: ${obj.payload?.timezone || ''}`,
      `model: ${obj.payload?.model || ''}`,
      `summary: ${obj.payload?.summary || ''}`,
    ].join('\n');
  } else if (type === 'response_item') {
    const p = obj.payload || {};
    title = `response_item/${p.type || 'unknown'}`;
    if (p.type === 'message') {
      body = `${p.role || 'unknown'}:\n${truncate(textFromContent(p.content), 2500)}`;
    } else if (p.type === 'function_call') {
      body = [`name: ${p.name || ''}`, `call_id: ${p.call_id || ''}`, `arguments:`, truncate(p.arguments || '', 2500)].join('\n');
    } else if (p.type === 'function_call_output') {
      body = [`call_id: ${p.call_id || ''}`, `output:`, truncate(p.output || '', 2500)].join('\n');
    } else if (p.type === 'reasoning') {
      const summary = Array.isArray(p.summary) ? p.summary.map(s => s.text || s).join('\n') : '';
      body = summary ? `summary:\n${truncate(summary, 1500)}` : 'encrypted or empty reasoning content; see raw JSONL.';
    } else {
      body = truncate(JSON.stringify(p, null, 2), 2500);
    }
  } else if (type === 'event_msg') {
    const p = obj.payload || {};
    title = `event_msg/${p.type || 'unknown'}`;
    if (p.message) body = truncate(p.message, 2500);
    else if (p.last_agent_message) body = truncate(p.last_agent_message, 2500);
    else if (p.info) body = truncate(JSON.stringify(p.info, null, 2), 2500);
    else body = truncate(JSON.stringify(p, null, 2), 2500);
  } else {
    body = truncate(JSON.stringify(obj.payload, null, 2), 2500);
  }

  timeline.push(`## Line ${r.idx} — ${ts} — ${title}`);
  timeline.push('');
  timeline.push(codeFence(body));
  timeline.push('');
}

timeline.splice(5, 0, `- Event counts: ${Object.entries(counters).map(([k, v]) => `${k}=${v}`).join(', ')}`);

let historyMatches = [];
if (fs.existsSync(historyPath)) {
  for (const r of readJsonl(historyPath)) {
    if (r.obj?.session_id === sessionId || r.raw.includes(sessionId)) historyMatches.push(r);
  }
}
let historyMd = [];
historyMd.push(`# History Index Matches: ${sessionId}`);
historyMd.push('');
historyMd.push(`- Exported at: ${new Date().toISOString()}`);
historyMd.push(`- Source snapshot: ${historyPath}`);
historyMd.push(`- Matches found: ${historyMatches.length}`);
historyMd.push('');
if (historyMatches.length) {
  for (const r of historyMatches) {
    historyMd.push(`## Line ${r.idx}`);
    historyMd.push('');
    historyMd.push(codeFence(JSON.stringify(r.obj, null, 2)));
    historyMd.push('');
  }
} else {
  historyMd.push('No records in `raw/global-history-snapshot.jsonl` matched this session ID. The full conversation is present in the raw session JSONL export.');
  historyMd.push('');
}

fs.writeFileSync(path.join(outDir, 'transcript.md'), transcript.join('\n'));
fs.writeFileSync(path.join(outDir, 'timeline.md'), timeline.join('\n'));
fs.writeFileSync(path.join(outDir, 'history-index-matches.md'), historyMd.join('\n'));

const manifest = {
  session_id: sessionId,
  exported_at: new Date().toISOString(),
  source_session_jsonl: '/Users/lyston/.codex/sessions/2026/05/13/rollout-2026-05-13T10-21-10-019e1f23-57e7-7110-ba2c-c18698f4f8ec.jsonl',
  source_history_jsonl: '/Users/lyston/.codex/history.jsonl',
  source_skill_dir: '/Users/lyston/.codex/skills/ad-creative-script',
  output_root: root,
  session_meta: metaRow,
  counts: { source_lines: rows.length, visible_transcript_messages: messageCount, event_types: counters, history_matches: historyMatches.length },
  notes: [
    'Raw JSONL is the complete session record found locally.',
    'Readable transcript extracts visible user and assistant message text only.',
    'Timeline is a compact index and truncates long payloads; consult raw JSONL for full payloads.',
    'Encrypted reasoning blobs cannot be converted to readable text here and are preserved verbatim in raw JSONL.',
    'Global history snapshot is included as a separate raw file; no direct target session_id match was found at export time.'
  ]
};
fs.writeFileSync(path.join(root, 'manifest.json'), JSON.stringify(manifest, null, 2));
